-- Canonical reference catalogue, separate from actual Loculary implementations.
-- Existing entries remain unverified leads until their identity and official references are checked individually.
create table public.design_audit_catalog_entries (
  id text primary key check (id ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name text not null,
  category text not null,
  catalog_scope text not null check (catalog_scope in ('material-3', 'loculary')),
  entry_type text not null check (entry_type in ('component', 'variant', 'pattern', 'api-concept', 'utility', 'composition')),
  classification_note text not null,
  reference_status text not null default 'unverified' check (reference_status in ('unverified', 'verified', 'not-applicable')),
  official_reference_url text check (official_reference_url is null or official_reference_url ~ '^https://'),
  implementation_component_id text references public.design_audit_components(id) on delete set null,
  sort_order integer not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint design_audit_catalog_scope_reference_check check (
    (catalog_scope = 'material-3' and reference_status <> 'not-applicable') or
    (catalog_scope = 'loculary' and reference_status = 'not-applicable')
  )
);
comment on table public.design_audit_catalog_entries is 'Reference catalogue for Material 3 and Loculary-specific concepts. Kept separate from actual production implementations; unverified entries are leads, not claims of official M3 identity.';
comment on column public.design_audit_catalog_entries.catalog_scope is 'material-3 contains M3 concepts, variants and AndroidX API concepts that require source verification; loculary contains Loculary-specific compositions/utilities.';
create index design_audit_catalog_scope_category_order_idx on public.design_audit_catalog_entries(catalog_scope, category, sort_order);
create index design_audit_catalog_implementation_idx on public.design_audit_catalog_entries(implementation_component_id) where implementation_component_id is not null;
alter table public.design_audit_catalog_entries enable row level security;
revoke all on table public.design_audit_catalog_entries from anon, authenticated;
create policy "Audit readers can read reference catalogue" on public.design_audit_catalog_entries for select to authenticated using ((select private.has_admin_permission('audit.read')));
grant select on public.design_audit_catalog_entries to authenticated;
on conflict (id) do nothing;
update public.design_audit_catalog_entries e set implementation_component_id = c.id from public.design_audit_components c where e.catalog_scope = 'loculary' and e.id = c.id and e.implementation_component_id is null;
update public.design_audit_catalog_entries e set implementation_component_id = c.id from public.design_audit_components c where (e.id, c.id) in (('select-native-html-wrapper','select'),('textarea-web-wrapper','text-area')) and e.implementation_component_id is null;
create trigger design_audit_catalog_entries_updated_at before update on public.design_audit_catalog_entries for each row execute function private.set_design_audit_updated_at();
